css:
.ag-head td { vertical-align: top; }
.ag-box { border: 1px solid #999; padding: 6px 8px; margin: 8px 0; }
.ag-box td { padding: 1px 6px 1px 0; font-size: 11px; }
.ag-cancel { color: #c0392b; font-weight: bold; font-size: 14px; border: 2px solid #c0392b; padding: 4px 8px; display: inline-block; margin: 6px 0; }
.ag-items th, .ag-items td { border: 1px solid #ccc; padding: 4px; font-size: 11px; }
.ag-items { width: 100%; border-collapse: collapse; }
.ag-right { text-align: right; }
.ag-qr img { width: 130px; }

html:
{%- set einv = doc.aitsgst_einvoice_status -%}
{%- set ewb = doc.aitsgst_ewb_status -%}
<table class="ag-head" style="width:100%">
 <tr>
  <td style="width:65%">
   <h3 style="margin:0">{{ doc.company }}</h3>
   <div>GSTIN: <b>{{ doc.company_gstin or '' }}</b></div>
   <h4 style="margin:8px 0 0">{{ _("Credit Note") if doc.is_return else _("Tax Invoice") }}</h4>
   <div>{{ _("Invoice No") }}: <b>{{ doc.name }}</b> &nbsp; {{ _("Date") }}: <b>{{ doc.get_formatted("posting_date") }}</b></div>
   {% if doc.po_no %}<div>{{ _("PO No") }}: {{ doc.po_no }}</div>{% endif %}
  </td>
  <td class="ag-qr ag-right">
   {% if doc.aitsgst_signed_qr_code and einv == "Generated" %}
    <img src="{{ get_qr_data_uri(doc.aitsgst_signed_qr_code) }}" alt="e-Invoice QR">
   {% endif %}
  </td>
 </tr>
</table>

{% if einv == "Cancelled" %}<div class="ag-cancel">{{ _("e-INVOICE (IRN) CANCELLED") }}{% if doc.aitsgst_einvoice_cancel_reason %} - {{ doc.aitsgst_einvoice_cancel_reason }}{% endif %}</div>{% endif %}

{% if doc.aitsgst_irn or doc.aitsgst_ewaybill %}
<div class="ag-box"><table>
 {% if doc.aitsgst_irn %}
 <tr><td>IRN</td><td><b style="word-break:break-all">{{ doc.aitsgst_irn }}</b></td></tr>
 <tr><td>{{ _("Ack No") }}</td><td>{{ doc.aitsgst_ack_no or '' }}</td></tr>
 <tr><td>{{ _("Ack Date") }}</td><td>{{ doc.get_formatted("aitsgst_ack_date") if doc.aitsgst_ack_date else '' }}</td></tr>
 {% endif %}
 {% if doc.aitsgst_ewaybill %}
 <tr><td>{{ _("e-Way Bill No") }}</td><td><b>{{ doc.aitsgst_ewaybill }}</b>{% if ewb == "Cancelled" %} <span style="color:#c0392b">({{ _("Cancelled") }})</span>{% endif %}</td></tr>
 <tr><td>{{ _("Valid Upto") }}</td><td>{{ doc.get_formatted("aitsgst_ewb_valid_upto") if doc.aitsgst_ewb_valid_upto else '' }}</td></tr>
 {% if doc.aitsgst_vehicle_no %}<tr><td>{{ _("Vehicle No") }}</td><td>{{ doc.aitsgst_vehicle_no }}</td></tr>{% endif %}
 {% endif %}
</table></div>
{% endif %}

<table style="width:100%; margin:6px 0">
 <tr>
  <td style="width:50%; vertical-align:top">
   <b>{{ _("Bill To") }}</b><br>{{ doc.customer_name }}<br>
   {{ doc.address_display or '' }}
   {% if doc.billing_address_gstin %}<br>GSTIN: <b>{{ doc.billing_address_gstin }}</b>{% endif %}
  </td>
  <td style="vertical-align:top">
   <b>{{ _("Ship To") }}</b><br>{{ doc.shipping_address or doc.address_display or '' }}
   <br>{{ _("Place of Supply") }}: <b>{{ doc.place_of_supply or '' }}</b>
  </td>
 </tr>
</table>

<table class="ag-items">
 <thead><tr>
  <th>#</th><th>{{ _("Description") }}</th><th>HSN/SAC</th><th class="ag-right">{{ _("Qty") }}</th><th>{{ _("UOM") }}</th><th class="ag-right">{{ _("Rate") }}</th><th class="ag-right">{{ _("Amount") }}</th>
 </tr></thead>
 <tbody>
 {% for row in doc.items %}
  <tr>
   <td>{{ row.idx }}</td><td>{{ row.item_name }}</td><td>{{ row.gst_hsn_code or '' }}</td>
   <td class="ag-right">{{ row.get_formatted("qty") }}</td><td>{{ row.uom }}</td>
   <td class="ag-right">{{ row.get_formatted("rate", doc) }}</td><td class="ag-right">{{ row.get_formatted("amount", doc) }}</td>
  </tr>
 {% endfor %}
 </tbody>
</table>

<table style="width:100%; margin-top:6px">
 <tr><td style="width:60%"></td><td>{{ _("Net Total") }}</td><td class="ag-right">{{ doc.get_formatted("net_total") }}</td></tr>
 {% for tax in doc.taxes %}{% if tax.tax_amount %}
 <tr><td></td><td>{{ tax.description }}</td><td class="ag-right">{{ tax.get_formatted("tax_amount", doc) }}</td></tr>
 {% endif %}{% endfor %}
 {% if doc.rounding_adjustment %}<tr><td></td><td>{{ _("Rounding") }}</td><td class="ag-right">{{ doc.get_formatted("rounding_adjustment") }}</td></tr>{% endif %}
 <tr><td></td><td><b>{{ _("Grand Total") }}</b></td><td class="ag-right"><b>{{ doc.get_formatted("rounded_total") if doc.rounded_total else doc.get_formatted("grand_total") }}</b></td></tr>
</table>
<div style="margin-top:6px">{{ _("In Words") }}: {{ doc.in_words or '' }}</div>
